TEXT ·hasAVX512BW(SB), NOSPLIT, $0-1
	MOVB $0, ret+0(FP)
	XORL AX, AX
	CPUID
	CMPL AX, $7
	JL hasAVX512BW_unsupported
	MOVL $1, AX
	CPUID
	ANDL $0x18000000, CX // AVX and OSXSAVE
	CMPL CX, $0x18000000
	JNE hasAVX512BW_unsupported
	XORL CX, CX
	XGETBV
	ANDL $0xE6, AX // XMM, YMM, opmask, ZMM_Hi256 and Hi16_ZMM state in XCR0
	CMPL AX, $0xE6
	JNE hasAVX512BW_unsupported
	MOVL $7, AX
	XORL CX, CX
	CPUID
	ANDL $0x40010000, BX // AVX512F and AVX512BW
	CMPL BX, $0x40010000
	JNE hasAVX512BW_unsupported
	MOVB $1, ret+0(FP)
hasAVX512BW_unsupported:
	RET

TEXT ·hasAVX512VBMI(SB), NOSPLIT, $0-1
	MOVB $0, ret+0(FP)
	XORL AX, AX
	CPUID
	CMPL AX, $7
	JL hasAVX512VBMI_unsupported
	MOVL $1, AX
	CPUID
	ANDL $0x18000000, CX // AVX and OSXSAVE
	CMPL CX, $0x18000000
	JNE hasAVX512VBMI_unsupported
	XORL CX, CX
	XGETBV
	ANDL $0xE6, AX // XMM, YMM, opmask, ZMM_Hi256 and Hi16_ZMM state in XCR0
	CMPL AX, $0xE6
	JNE hasAVX512VBMI_unsupported
	MOVL $7, AX
	XORL CX, CX
	CPUID
	ANDL $0x40010000, BX // AVX512F and AVX512BW
	CMPL BX, $0x40010000
	JNE hasAVX512VBMI_unsupported
	TESTL $0x2, CX // AVX512VBMI
	JZ hasAVX512VBMI_unsupported
	MOVB $1, ret+0(FP)
hasAVX512VBMI_unsupported:
	RET

TEXT ·hasGFNI(SB), NOSPLIT, $0-1
	MOVB $0, ret+0(FP)
	XORL AX, AX
	CPUID
	CMPL AX, $7
	JL hasGFNI_unsupported
	MOVL $1, AX
	CPUID
	ANDL $0x18000000, CX // AVX and OSXSAVE
	CMPL CX, $0x18000000
	JNE hasGFNI_unsupported
	XORL CX, CX
	XGETBV
	ANDL $0xE6, AX // XMM, YMM, opmask, ZMM_Hi256 and Hi16_ZMM state in XCR0
	CMPL AX, $0xE6
	JNE hasGFNI_unsupported
	MOVL $7, AX
	XORL CX, CX
	CPUID
	TESTL $0x10000, BX // AVX512F, for the 512-bit form
	JZ hasGFNI_unsupported
	TESTL $0x100, CX // GFNI
	JZ hasGFNI_unsupported
	MOVB $1, ret+0(FP)
hasGFNI_unsupported:
	RET

